<template><view class="p"><jk-page-nav title="提现详情"/><view v-if="detail" class="card"><view class="row"><text>提现单号</text><b>{{detail.withdrawNo || '--'}}</b></view><view class="row"><text>申请人</text><b>{{detail.applicantName || '用户不存在'}}<text v-if="detail.applicantPhone"> / {{detail.applicantPhone}}</text></b></view><view class="row"><text>身份</text><b>{{detail.roleName || '身份未配置'}}</b></view><view class="row"><text>提现金额</text><b>¥ {{detail.amount || 0}}</b></view><view class="row"><text>状态</text><b>{{detail.withdrawStatusText || detail.statusText || withdrawStatusText(detail.status)}}</b></view><view class="row"><text>申请时间</text><b>{{detail.createTime || '--'}}</b></view><view class="row" v-if="detail.rejectReason"><text>驳回原因</text><b>{{detail.rejectReason}}</b></view><view class="row"><text>收款信息</text><b>{{detail.payeeSnapshotJson || '--'}}</b></view></view></view></template><script>import JkPageNav from '@/components/jk/jk-page-nav.vue';import{getJkWithdrawDetail}from'@/api/jk.js';import{jkWithdrawStatusText}from'@/utils/jk-display.js';export default{components:{JkPageNav},data(){return{detail:null}},onLoad(q){getJkWithdrawDetail(q.id).then(r=>this.detail=r.data||r||{})},methods:{withdrawStatusText(status){return jkWithdrawStatusText(status)}}}</script><style scoped>.p{min-height:100vh;background:#f3fbf8;padding:24rpx}.card{background:#fff;padding:24rpx;border-radius:18rpx;display:flex;flex-direction:column;gap:18rpx}.row{display:flex;justify-content:space-between;gap:20rpx}.row text{color:#78918b}.row b{color:#183a36;text-align:right}</style>
